const AZ_ASSET_REGISTRY = JSON.parse(document.getElementById('az-asset-manifest').textContent);
/* Владелец, 27 ноября: умения из поздних дополнений заменены классическими (ключи сохранены): «Удар воина Света» → «Печать праведности», «Верный выстрел» → «Оглушающий выстрел». */
(function () {
  const icon = function (name, file) { return { name: name, icon: file, url: 'https://wow.zamimg.com/images/wow/icons/large/' + file + '.jpg', category: 'active', verified: false }; };
  const fix = { crusader: icon('Печать праведности', 'ability_thunderbolt'), steady: icon('Оглушающий выстрел', 'spell_frost_stun') };
  Object.keys(fix).forEach(function (k) {
    if (AZ_ASSET_REGISTRY.assets && AZ_ASSET_REGISTRY.assets['skill:' + k]) AZ_ASSET_REGISTRY.assets['skill:' + k] = fix[k];
    if (AZ_ASSET_REGISTRY.skills && AZ_ASSET_REGISTRY.skills[k]) AZ_ASSET_REGISTRY.skills[k] = fix[k];
  });
})();
